import{z as A,x as n,o as t,c as p,q as i,j as s,D as E,d as l,s as o,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"干法显影胶","description":"","frontmatter":{"title":"干法显影胶","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dry-resist-develop.md","filePath":"litho/dry-resist-develop.md","lastUpdated":1791063341000}'),d={name:"litho/dry-resist-develop.md"};function m(D,a,h,u,C,f){const r=n("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="干法显影胶" tabindex="-1">干法显影胶 <a class="header-anchor" href="#干法显影胶" aria-label="Permalink to &quot;干法显影胶&quot;">​</a></h1><div class="epigraph"><p>湿法显影把链溶进液体，毛细力与溶解噪声一起到场；干法显影用等离子体或气相选择比去掉未成像部分，换的是噪声通道和倒塌预算，不是取消随机。</p><footer>—— 据干法抗蚀剂 / 干法显影的公开工艺叙述（气相沉积金属胶与等离子体显影一类）</footer></div><p><a href="/litho/mor-stochastics">上一课</a>把 MOR 的团簇随机写完，默认仍可走湿法显影。缺口是另一条工艺边：干法显影胶——成像层气相沉积、显影用干法选择比，而不是 TMAH puddle。本课钉机制与随机含义，作为「计数噪声到缺陷」课序的收束。下一课程从<a href="/litho/spin-coating-uniformity">旋涂均匀性</a>进入轨道，湿法涂布重新成为默认，但本课已声明干法栈存在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>湿法：\\(R(m)\\) 在液体里推进，毛细力矩倒塌，溶解前沿贡献 LER。<a href="/litho/pattern-collapse">倒塌</a> 与深宽比在 High-NA 薄膜预算里已经很紧。干法显影用等离子体（或气相反应）按化学状态选择去除，毛细通道取消，倒塌预算换成形貌与选择比：过显影啃侧壁，欠显影留残渣，看起来像桥或 footing。</p><p><span class="marginnote">选择比（selectivity）翻译过来是「偏心啃」的程度：等离子体对未成像区与成像区的去除速率之比，10:1 就是同样时间里没曝光的部分被啃掉 10 倍厚。比例不是无穷大，所以过头了会啃侧壁，不够了会留残渣。</span></p><p>气相沉积（干法涂布）可以做得很薄、含金属以提高 EUV 吸收，与上一课 MOR 吸收策略同向，但成膜不再是旋涂分子量那一套。缺口不是再写锡氧配体，而是：随机从「溶解噪声 + 毛细」换成「沉积离散 + 等离子体选择比 + 仍在的光子/电子」。</p><h3 id="干法不是零随机" tabindex="-1">干法不是零随机 <a class="header-anchor" href="#干法不是零随机" aria-label="Permalink to &quot;干法不是零随机&quot;">​</a></h3><p>光子与二次电子仍在。沉积若以岛或晶粒生长，又是一套团簇计数。等离子体各向异性会把潜像噪声转印并可能放大侧壁。宣传「干法解决随机」若只展示倒塌改善，没有缺陷率曲线，等于没签核随机窗。</p><p><span class="marginnote">等离子体显影的各向异性可以想象成只从正上方喷砂：底面被均匀打掉，侧壁几乎不挨打，线条不会被液体「横向泡塌」。代价是潜像上的任何毛刺都会被竖直转印到侧壁上，噪声没消失，只是换了通道。</span></p><p><span class="marginnote">公开路线里 Lam 等讨论的 dry resist（干法沉积 + 干法显影）是这一课的工艺所指之一。课标是机制，不是商标或未公开配方。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>资格：剂量–CD、LCDU、缺陷 vs 剂量、侧壁、残渣、腔体沾污、与底层选择比。对照必须含同一光学下的湿法 MOR/CAR，否则在比倒塌而不是比随机。OPC 紧凑模型要重校准：没有湿法 Notch，\\(R(m)\\) 换成干法速率对配体/网络分数的函数。MC 抽沉积岛与等离子体前沿，或至少换显影模块。</p><p>轨道含义：涂胶碗不再是成像层主路径，真空腔体颗粒与聚合物沉积均匀性变成 CDU 项。下一课程的旋涂课仍对 BARC/SOC 与湿法层有效。</p>',14)),(t(),s(B,null,{default:E(()=>[o(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEP%5B%22%E5%B9%B2%E6%B3%95%E6%B2%89%E7%A7%AF%E6%88%90%E5%83%8F%E5%B1%82%22%5D%20--%3E%20LAT%5B%22%E6%9B%9D%E5%85%89%E6%BD%9C%E5%83%8F%22%5D%0A%20%20LAT%20--%3E%20DRY%5B%22%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%20%2F%20%E6%B0%94%E7%9B%B8%E6%98%BE%E5%BD%B1%22%5D%0A%20%20DRY%20--%3E%20NOCAP%5B%22%E6%97%A0%E6%B9%BF%E6%B3%95%E6%AF%9B%E7%BB%86%22%5D%0A%20%20DRY%20--%3E%20SEL%5B%22%E9%80%89%E6%8B%A9%E6%AF%94%20%2F%20%E6%AE%8B%E6%B8%A3%22%5D%0A%20%20STO%5B%22%E5%85%89%E5%AD%90%20%E7%94%B5%E5%AD%90%20%E6%B2%89%E7%A7%AF%E7%A6%BB%E6%95%A3%22%5D%20--%3E%20DRY%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"潜像仍是化学状态的空间图（配体密度、交联、金属–氧网络）。干法前沿的法向速度由选择比与局部状态决定，类比 \\(R(m)\\)，介质是等离子体而非 TMAH。选择比有限时，过刻把 CD 拉开，欠刻桥接。没有液体，倒塌的毛细项消失，但薄膜应力与等离子体诱生粗糙还在。",-1)),a[5]||(a[5]=e("p",null,"沉积离散：气相生长的厚度泊松或岛状成核，薄到十几纳米时相对涨落可观，这是新的 \\(N\\)。吸收金属提高光子利用率，与 MOR 课同一 S 角逻辑。腔体交叉污染是系统缺陷通道，对拍重复性，不要并进光子泊松。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"数字实例：成像层只有 10 nm 厚时，沿厚度方向大约只有几十个可分辨单元，若按泊松计数，厚度相对涨落约在 \\(1/\\sqrt{50}\\approx 14\\%\\) 量级——远大于湿法旋涂的膜厚噪声。薄膜越薄，离散沉积的「颗粒感」越显，这就是文中说的新的 \\(N\\)。")],-1)),(t(),s(B,null,{default:E(()=>[o(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20QE%5B%22%E5%85%89%E5%AD%90%E4%B8%8E%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%E8%AE%A1%E6%95%B0%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20L1%5B%22%E6%B9%BF%E6%B3%95%EF%BC%9ALER%20%2F%20%E7%BC%BA%E9%99%B7%22%5D%0A%20%20QE%20--%3E%20L2%5B%22%E5%B9%B2%E6%B3%95%EF%BC%9ALER%20%2F%20%E7%BC%BA%E9%99%B7%22%5D%0A%20%20D1%5B%22%E6%BA%B6%E8%A7%A3%E5%99%AA%E5%A3%B0%20R(m)%22%5D%20--%3E%20L1%0A%20%20CAP%5B%22%E6%AF%9B%E7%BB%86%E5%8A%9B%E5%80%92%E5%A1%8C%22%5D%20--%3E%20L1%0A%20%20DEP%5B%22%E6%B2%89%E7%A7%AF%E7%A6%BB%E6%95%A3%EF%BC%9A%E5%B2%9B%E7%8A%B6%E6%88%90%E6%A0%B8%22%5D%20--%3E%20L2%0A%20%20SEL%5B%22%E9%80%89%E6%8B%A9%E6%AF%94%E6%9C%89%E9%99%90%EF%BC%9A%E6%AE%8B%E6%B8%A3%2F%E5%95%83%E4%BE%A7%E5%A3%81%22%5D%20--%3E%20L2%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">湿法显影的表面活性剂与冲洗规对干法栈不适用。去胶与灰化路径也要重开。集成约束与锡氧课的沾污门同类。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写腔体食谱、不编选择比「标准值」、不宣布某节点已切换干法。本课程平均场从 Dill 走到轮廓，随机从计数走到缺陷；干法显影是显影模块的另一实现，ABC 与光子统计仍然成立。下一课程轨道工艺默认湿法旋涂，遇到干法成像层时回到本课换模块，不要把 spin-speed 公式套到 CVD 上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>干法显影用选择比去掉未成像部分，取消湿法毛细倒塌，换来残渣与等离子体粗糙。</li><li>随机仍含光子、电子与沉积离散；必须交缺陷曲线。</li><li>紧凑 \\(R(m)\\) 与 MC 显影模块要换族。</li><li>公开 dry resist 路线是工艺实例，不是牌号课。</li><li>出处：干法抗蚀剂公开工艺叙述；Naulleau 随机一般框架；上一课 MOR。</li></ul>',5))])}const _=A(d,[["render",m]]);export{R as __pageData,_ as default};
